// 从 import-*.json 日志剔除误记 done 的失败批标题
import fs from "fs";
import path from "path";

const TMP = process.env.TEMP;
const PROJECTS = ["苏住房C", "产品2.0", "门户"];

function failedTitles(logPath) {
  if (!fs.existsSync(logPath)) return new Set();
  const j = JSON.parse(fs.readFileSync(logPath, "utf8"));
  const bad = new Set();
  for (const b of j.batches || []) {
    const st = b.result?.status;
    const w = b.result?.extracted?.memory_write ?? 0;
    const e = b.result?.extracted?.memory_edit ?? 0;
    if (st === "failed" || b.error === "commit timeout" || (st === "completed" && w === 0 && e === 0)) {
      for (const t of b.titles || []) bad.add(t);
    }
  }
  return bad;
}

const summary = [];
for (const project of PROJECTS) {
  const donePath = path.join(TMP, `done-${project}.json`);
  if (!fs.existsSync(donePath)) continue;
  const logPath = path.join(TMP, `import-${project}.json`);
  const bad = failedTitles(logPath);
  const arr = JSON.parse(fs.readFileSync(donePath, "utf8"));
  const before = arr.length;
  const next = arr.filter((t) => !bad.has(t));
  if (next.length !== before) {
    fs.writeFileSync(donePath, JSON.stringify(next, null, 1), "utf8");
  }
  summary.push({ project, before, after: next.length, removed: before - next.length, retryQueue: bad.size });
  console.log(project, "done", before, "→", next.length, "removed", before - next.length, "log-failed", bad.size);
}

const outDir = path.join(path.dirname(new URL(import.meta.url).pathname.replace(/^\//, "C:/")), "..", "out");
const outPath = "C:\\Users\\Administrator\\Documents\\deepseek-harness\\default-workspace\\memory-migration\\out\\align-reconcile.json";
fs.writeFileSync(outPath, JSON.stringify({ at: new Date().toISOString(), summary }, null, 2));
console.log("Wrote", outPath);

// 对齐：distilled 标题 vs done 集合
import fs from "fs";
import path from "path";
import os from "os";

const BASE = "C:\\Users\\Administrator\\Documents\\deepseek-harness\\default-workspace\\memory-migration";
const SRC = path.join(BASE, "out", "distilled-projects");
const TMP = process.env.TEMP;
const PROJECTS = ["苏住房C", "产品2.0", "门户"];

function loadTitles(project) {
  const dir = path.join(SRC, project);
  const titles = [];
  for (const f of fs.readdirSync(dir).filter((x) => x.endsWith(".json"))) {
    const j = JSON.parse(fs.readFileSync(path.join(dir, f), "utf8"));
    for (const m of j.memories || []) titles.push(m.title);
  }
  return titles;
}

const report = { at: new Date().toISOString(), projects: [] };
for (const project of PROJECTS) {
  const entries = loadTitles(project);
  const unique = [...new Set(entries)];
  const donePath = path.join(TMP, `done-${project}.json`);
  const done = new Set(fs.existsSync(donePath) ? JSON.parse(fs.readFileSync(donePath, "utf8")) : []);
  const missing = unique.filter((t) => !done.has(t));
  const dupInSource = entries.length - unique.length;
  report.projects.push({
    project,
    entries: entries.length,
    uniqueTitles: unique.length,
    doneCount: done.size,
    missingUnique: missing.length,
    duplicateEntriesInSource: dupInSource,
    missingTitles: missing.slice(0, 30),
    aligned: missing.length === 0,
  });
  console.log(
    project,
    "unique",
    unique.length,
    "done",
    done.size,
    "missing",
    missing.length,
    "src-dupes",
    dupInSource,
    missing.length ? "NOT_ALIGNED" : "OK"
  );
}

const outPath = path.join(BASE, "out", "align-report.json");
fs.writeFileSync(outPath, JSON.stringify(report, null, 2), "utf8");
console.log("Wrote", outPath);
process.exit(report.projects.some((p) => !p.aligned) ? 2 : 0);

// 去重：同名 slug 多路径 → 保留最Rich + 优先中文目录，其余移入 quarantine
import fs from "fs";
import path from "path";
import os from "os";
import crypto from "crypto";

const DRY = process.argv.includes("--dry");
const MEM = path.join(os.homedir(), ".openviking/data/viking/default/user/default/memories");
const QUAR = path.join(
  "C:\\Users\\Administrator\\Documents\\deepseek-harness\\default-workspace\\memory-migration",
  "out",
  "dedupe-quarantine",
  new Date().toISOString().replace(/[:.]/g, "-")
);

const BAD_DIR = /padrão|estrutura de|projeto de|padrão técnico|technical_pattern/i;
const PREFER = /entities\/技术模式|entities\/前端|entities\/工作流|entities\/苏州市|preferences\/user/;

function scorePath(rel, bodyLen) {
  let s = bodyLen;
  if (PREFER.test(rel)) s += 5000;
  if (BAD_DIR.test(rel)) s -= 8000;
  if (rel.includes(".overview")) s -= 10000;
  return s;
}

const files = [];
function walk(d) {
  for (const e of fs.readdirSync(d, { withFileTypes: true })) {
    const p = path.join(d, e.name);
    if (e.isDirectory()) walk(p);
    else if (e.name.endsWith(".md") && e.name !== ".overview.md") files.push(p);
  }
}
walk(MEM);

const byBase = new Map();
for (const f of files) {
  const rel = path.relative(MEM, f).replace(/\\/g, "/");
  const base = path.basename(f, ".md").toLowerCase();
  const raw = fs.readFileSync(f, "utf8");
  const body = raw.replace(/<!-- MEMORY_FIELDS[\s\S]*?-->/g, "").trim();
  if (!byBase.has(base)) byBase.set(base, []);
  byBase.get(base).push({ rel, abs: f, bodyLen: body.length, score: scorePath(rel, body.length) });
}

const actions = [];
let moved = 0;
for (const [base, items] of byBase.entries()) {
  if (items.length < 2) continue;
  items.sort((a, b) => b.score - a.score);
  const keep = items[0];
  for (const loser of items.slice(1)) {
    actions.push({ base, keep: keep.rel, remove: loser.rel, keepScore: keep.score, loserScore: loser.score });
    if (!DRY) {
      const dest = path.join(QUAR, loser.rel);
      fs.mkdirSync(path.dirname(dest), { recursive: true });
      fs.renameSync(loser.abs, dest);
      moved++;
    }
  }
}

// 葡语误分类整目录：若目录下 .md 已全部移走或只剩 overview，移走剩余
const foreignRoots = [
  "entities/padrão técnico",
  "entities/estrutura de código",
  "entities/estrutura de projeto",
  "entities/projeto de software",
  "entities/padrão técnico",
];
